using namespace std;

int main() {
    int count;
    cin >> count;

    // 1. Read count integers into vector<int> signals with push_back
    // 2. Calculate sum of all signals
    // 3. Find max_signal initialized to signals[0]
    // 4. Print TOTAL SIGNAL: sum
    // 5. Print PEAK SIGNAL: max_signal

    return 0;
}

steps.solution:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int count;
    cin >> count;

    vector<int> signals;
    for (int i = 0; i < count; i++) {
        int s;
        cin >> s;
        signals.push_back(s);
    }

    int sum = 0;
    int max_signal = signals[0];

    for (int i = 0; i < signals.size(); i++) {
        sum += signals[i];
        if (signals[i] > max_signal) {
            max_signal = signals[i];
        }
    }

    cout << "TOTAL SIGNAL: " << sum << endl;
    cout << "PEAK SIGNAL: " << max_signal << endl;

    return 0;
}

