    // 1. Read n altitude values into vector<int> altitudes with push_back
    // 2. Count waypoints where altitude >= 100
    // 3. Accumulate total altitude
    // 4. Print WAYPOINTS LOGGED: altitudes.size()
    // 5. Print TOTAL ALTITUDE: total
    // 6. Print HIGH ALTITUDE FIXES: count

    return 0;
}

steps.solution:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> altitudes;
    for (int i = 0; i < n; i++) {
        int alt;
        cin >> alt;
        altitudes.push_back(alt);
    }

    int high_altitude_count = 0;
    int total_alt = 0;

    for (int i = 0; i < altitudes.size(); i++) {
        total_alt += altitudes[i];
        if (altitudes[i] >= 100) {
            high_altitude_count++;
        }
    }

    cout << "WAYPOINTS LOGGED: " << altitudes.size() << endl;
    cout << "TOTAL ALTITUDE: " << total_alt << endl;
    cout << "HIGH ALTITUDE FIXES: " << high_altitude_count << endl;

    return 0;
}
